# Lanternhold v132: public / private hero profile. Paste into AWS CloudShell (us-east-1). Needs John's go.
# Updates three functions so the Players Guild honours each player's "show / hide" switches:
#   lanternhold-heroes  stores the public showcase (stats, gear, records, party) and strips hidden parts from GET /heroes.
#                       This heroes.js ALSO contains v132 unique names (PR #56), so it replaces unique-names-cloudshell.sh.
#                       It also has the v132 ?p=1 party-only refresh (PR #64).
#   lanternhold-profile accepts the hidden list (pf.h) on PUT /profile.
#   lanternhold-invite  hides online status, bio and war badge on invites when the player hid them.
# No new permissions, tables or routes. Backs up each function first. Safe to run twice.
set -e
TS=$(date +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhprofile && cd ~/lhprofile
deploy() { # $1 function, $2 base64 source
  curl -s "$(aws lambda get-function --function-name $1 --query Code.Location --output text)" -o ~/lhbak/$1-$TS.zip
  echo "$2" | base64 -d > index.js && rm -f f.zip && zip -qj f.zip index.js
  aws lambda update-function-code --function-name $1 --zip-file fileb://f.zip >/dev/null
  aws lambda wait function-updated --function-name $1
  echo "$1 updated (backup ~/lhbak/$1-$TS.zip)"
}
deploy lanternhold-heroes 
deploy lanternhold-profile 
deploy lanternhold-invite 
echo "Done. Undo one: aws lambda update-function-code --function-name <name> --zip-file fileb://$HOME/lhbak/<name>-$TS.zip"
